<script setup lang="ts">
import { useAccountStore } from '~/stores/account'
import { getHttpErrorMessage } from '~/utils/httpError'
import AchievementBadge from '~/components/achievement/AchievementBadge.vue'
type User = { id: string; username: string; phone: string | null; role: string; balance: number; blockedAt: string | null; deletedAt: string | null; updatedAt?: string }
type Detail = User & Record<string, any>
const account = useAccountStore(); const error = ref(''); const notice = ref(''); const loading = ref(true); const activeTab = ref('overview')
const userDialog = ref<HTMLDialogElement | null>(null)
function closeUserDialog() { if (!submitting.value) { ++detailRequest; selected.value = null } }
const query = ref(''); const users = ref<User[]>([]); const selected = ref<Detail | null>(null); const submitting = ref(false); const overview = ref<any>(null); const economy = ref<any>(null); const seasons = ref<any[]>([]); const audits = ref<any[]>([]); const achievements = ref<any[]>([]); const adminTelegram = reactive({ enabled: true, categories: { payments: true, users: true, games: true, premium: true, achievements: true } as Record<string, boolean> }); const adminTelegramReason = ref(''); const adminTelegramPassword = ref('')
watch(() => Boolean(selected.value), open => {
  if (open && !userDialog.value?.open) userDialog.value?.showModal()
  else if (!open && userDialog.value?.open) userDialog.value.close()
}, { flush: 'post' })
const form = reactive({ action: 'credit', amount: 5000, expectedBalance: 0, reason: '', password: '' }); const edit = reactive<Record<string, any>>({}); const premiumForm = reactive({ plan: 'LITE' as 'LITE' | 'PRO' | 'ELITE', reason: '', password: '' }); const economyEdit = reactive({ minesBank: 0, rocketBank: 0, jackpotTenths: 0, expectedUpdatedAt: '', reason: '', password: '' })
const canOpen = computed(() => ['ADMIN', 'SUPERADMIN'].includes(account.user?.role || '')); const tabs = [{ id: 'overview', label: 'Обзор', icon: '◈' }, { id: 'users', label: 'Участники', icon: '♙' }, { id: 'economy', label: 'Мини-игры', icon: '✦' }, { id: 'seasons', label: 'Сезоны', icon: '◒' }, { id: 'audit', label: 'Аудит', icon: '◌' }]
const money = (value: number | string | null | undefined) => Number(value || 0).toLocaleString('ru-RU'); const date = (value?: string) => value ? new Date(value).toLocaleString('ru-RU', { dateStyle: 'short', timeStyle: 'short' }) : '—'; const request = () => crypto.randomUUID()
async function loadBase() { loading.value = true; error.value = ''; try { const [summary, list, econ, seasonList, auditList, achievementList, telegramSettings] = await Promise.all([$fetch('/api/admin/overview'), $fetch<{ items: User[] }>('/api/admin/users', { query: { q: query.value } }), $fetch('/api/admin/economy'), $fetch<any[]>('/api/admin/seasons'), $fetch<{ items: any[] }>('/api/admin/audit'), $fetch<any[]>('/api/admin/achievements'), $fetch<any>('/api/admin/telegram-notifications')]); overview.value = summary; users.value = list.items; economy.value = econ; seasons.value = seasonList; audits.value = auditList.items; achievements.value = achievementList; Object.assign(adminTelegram, telegramSettings); if (economy.value) Object.assign(economyEdit, { minesBank: Number(economy.value.minesBank), rocketBank: Number(economy.value.rocketBank), jackpotTenths: Math.round(Number(economy.value.jackpot || 0) * 10), expectedUpdatedAt: economy.value.updatedAt || '' }) } catch (cause) { error.value = getHttpErrorMessage(cause, 'Не удалось загрузить данные админ-панели') } finally { loading.value = false } }
let detailRequest = 0
async function loadDetail(user: User) {
  const sequence = ++detailRequest
  try {
    const detail = await $fetch<Detail>(`/api/admin/users/${user.id}`)
    if (sequence !== detailRequest) return
    selected.value = detail
    Object.assign(edit, detail)
    premiumForm.plan = detail.premium?.plan || 'LITE'
    premiumForm.reason = ''; premiumForm.password = ''
    form.expectedBalance = Number(detail.balance)
    form.reason = ''; form.password = ''
  } catch (cause) { error.value = getHttpErrorMessage(cause, 'Не удалось открыть карточку') }
}
let balanceAttempt: { fingerprint: string; id: string } | null = null
async function basicCommand() {
  if (!selected.value || submitting.value) return
  const target = selected.value
  const fingerprint = JSON.stringify([target.id, form.action, form.amount, form.expectedBalance, form.reason])
  if (balanceAttempt?.fingerprint !== fingerprint) balanceAttempt = { fingerprint, id: request() }
  submitting.value = true; error.value = ''; notice.value = ''
  try {
    await $fetch(`/api/admin/users/${target.id}`, { method: 'POST', retry: 0, body: { ...form, amount: Number(form.amount), expectedBalance: Number(form.expectedBalance), requestId: balanceAttempt.id } })
    balanceAttempt = null
    await loadDetail(target)
    await loadBase()
    notice.value = 'Операция выполнена. Показан сохранённый баланс.'
  } catch (cause) {
    const message = getHttpErrorMessage(cause, 'Операция отклонена')
    const fresh = await $fetch<Detail>(`/api/admin/users/${target.id}`).catch(() => null)
    if (fresh) {
      selected.value = fresh
      if ((cause as { statusCode?: number }).statusCode === 409) { form.expectedBalance = Number(fresh.balance); balanceAttempt = null }
    }
    error.value = message
  } finally { submitting.value = false }
}
async function saveProfile() { if (!selected.value || submitting.value) return; submitting.value = true; error.value = ''; try { await $fetch(`/api/admin/users/${selected.value.id}/profile`, { method: 'POST', body: { expectedUpdatedAt: selected.value.updatedAt, username: edit.username, phone: edit.phone || null, role: edit.role, predictionRating: Number(edit.predictionRating), tableRating: Number(edit.tableRating), tableHandsPlayed: Number(edit.tableHandsPlayed), tableHandsWon: Number(edit.tableHandsWon), tableCurrentStreak: Number(edit.tableCurrentStreak), tableBestStreak: Number(edit.tableBestStreak), predictionCount: Number(edit.predictionCount), predictionWins: Number(edit.predictionWins), predictionSplitWins: Number(edit.predictionSplitWins), selectedAchievementCode: edit.selectedAchievementCode || null, reason: edit.reason, password: edit.password, requestId: request() } }); notice.value = 'Профиль сохранён'; await loadDetail(selected.value); await loadBase() } catch (cause) { error.value = getHttpErrorMessage(cause, 'Профиль не сохранён') } finally { submitting.value = false } }
async function achievementCommand(achievementId: string, mode: 'grant' | 'revoke') { if (!selected.value || submitting.value) return; const password = String(edit.password || prompt('Текущий пароль администратора') || ''); const reason = String(edit.reason || prompt('Причина изменения') || ''); if (!password || reason.length < 5) return; submitting.value = true; try { await $fetch(`/api/admin/users/${selected.value.id}/achievement`, { method: 'POST', body: { achievementId, mode, password, reason, requestId: request() } }); await loadDetail(selected.value); await loadBase() } catch (cause) { error.value = getHttpErrorMessage(cause, 'Достижение не изменено') } finally { submitting.value = false } }
async function resetMiniGames() { if (!selected.value || submitting.value) return; const password = String(edit.password || prompt('Текущий пароль администратора') || ''); const reason = String(edit.reason || prompt('Причина сброса мини-игр') || ''); if (!password || reason.length < 5) return; submitting.value = true; error.value = ''; try { await $fetch(`/api/admin/users/${selected.value.id}/minigames/reset`, { method: 'POST', body: { password, reason, requestId: request() } }); notice.value = 'Состояние и статистика мини-игр сброшены'; await loadDetail(selected.value); await loadBase() } catch (cause) { error.value = getHttpErrorMessage(cause, 'Мини-игры не сброшены') } finally { submitting.value = false } }
async function premiumCommand(action: 'assign' | 'extend' | 'disable') {
  if (!selected.value || submitting.value || !premiumForm.password || premiumForm.reason.trim().length < 5) return
  if (action === 'disable' && !confirm('Отключить Premium у этого пользователя?')) return
  const target = selected.value
  submitting.value = true; error.value = ''; notice.value = ''
  try {
    await $fetch(`/api/admin/users/${target.id}/premium`, { method: 'POST', retry: 0, body: { action, ...(action === 'assign' ? { plan: premiumForm.plan } : {}), reason: premiumForm.reason, password: premiumForm.password, requestId: request() } })
    notice.value = action === 'assign' ? `Premium ${premiumForm.plan} назначен на 30 дней` : action === 'extend' ? 'Premium продлён на 30 дней' : 'Premium отключён'
    await loadDetail(target); await loadBase()
  } catch (cause) { error.value = getHttpErrorMessage(cause, 'Premium не изменён') }
  finally { submitting.value = false }
}
async function saveEconomy() { if (submitting.value) return; submitting.value = true; try { await $fetch('/api/admin/economy', { method: 'POST', body: { ...economyEdit, minesBank: Number(economyEdit.minesBank), rocketBank: Number(economyEdit.rocketBank), jackpotTenths: Number(economyEdit.jackpotTenths), requestId: request() } }); notice.value = 'Банки мини-игр обновлены'; await loadBase() } catch (cause) { error.value = getHttpErrorMessage(cause, 'Банки не изменены') } finally { submitting.value = false } }
async function saveAdminTelegramSettings() { if (submitting.value || account.user?.role !== 'SUPERADMIN' || adminTelegramReason.value.trim().length < 5 || !adminTelegramPassword.value) return; submitting.value = true; error.value = ''; try { await $fetch('/api/admin/telegram-notifications', { method: 'POST', body: { enabled: adminTelegram.enabled, categories: { ...adminTelegram.categories }, reason: adminTelegramReason.value, password: adminTelegramPassword.value, requestId: request() } }); notice.value = 'Настройки Telegram-уведомлений сохранены'; adminTelegramReason.value = ''; adminTelegramPassword.value = '' } catch (cause) { error.value = getHttpErrorMessage(cause, 'Настройки Telegram не сохранены') } finally { submitting.value = false } }
watch(() => account.user?.id, () => { if (import.meta.client && canOpen.value) void loadBase() }, { immediate: true })
onMounted(() => { account.loadSession(); if (!account.user) loading.value = false })
</script>
<template>
  <main class="admin-page"><header class="topbar"><div class="brand"><span class="brand-mark">PD</span><div><p class="eyebrow">Control center · production</p><h1>Админ-панель</h1></div></div><div class="top-actions"><span class="live-dot">● Система онлайн</span><NuxtLink to="/profile" class="button ghost">Профиль</NuxtLink></div></header>
    <p v-if="!canOpen && !loading" class="notice error">Доступ доступен только подтверждённым администраторам.</p><p v-if="error" class="notice error">{{ error }}</p><p v-if="notice" class="notice success">{{ notice }}</p>
    <template v-if="canOpen"><nav class="tabs"><button v-for="tab in tabs" :key="tab.id" :class="{active: activeTab === tab.id}" @click="activeTab = tab.id">{{ tab.icon }} {{ tab.label }}</button></nav><section class="hero"><div><p class="eyebrow">Панель управления клубом</p><h2>Всё важное — в одном месте</h2><p class="muted">Баланс, прогресс игроков, сезоны и банки игр под контролем.</p></div><div class="orb">✦</div></section>
      <section v-if="activeTab === 'overview'" class="content"><div v-if="overview" class="metrics"><article><span>Игроки</span><b>{{ money(overview.users) }}</b><small>активных профилей</small></article><article><span>Очки в обороте</span><b>{{ money(overview.freePoints) }}</b><small>суммарный баланс</small></article><article><span>Комнаты</span><b>{{ money(overview.rooms) }}</b><small>{{ overview.liveHands }} раздач сейчас</small></article><article><span>Награды сегодня</span><b>{{ money(overview.rewardsToday) }}</b><small>завершённых сессий</small></article></div><div class="two-col"><article class="card"><p class="eyebrow">Быстрый доступ</p><h3>Рабочие разделы</h3><div class="quick"><button v-for="tab in tabs.slice(1)" :key="tab.id" @click="activeTab = tab.id"><strong>{{ tab.icon }}</strong><b>{{ tab.label }}</b><small>Открыть раздел →</small></button></div></article><article class="card"><p class="eyebrow">Безопасность</p><h3>Контроль изменений</h3><p class="muted">Каждое изменение требует текущий пароль администратора, проверяет актуальность данных и фиксируется в журнале аудита.</p><div class="audit-mini">Последняя запись <b>{{ audits[0] ? date(audits[0].createdAt) : 'Нет записей' }}</b></div></article><article class="card telegram-settings"><p class="eyebrow">Telegram · администраторы</p><h3>События для админов</h3><label class="toggle"><input v-model="adminTelegram.enabled" type="checkbox"><span>Отправлять уведомления</span></label><label v-for="(enabled, category) in adminTelegram.categories" :key="category" class="toggle compact"><input v-model="adminTelegram.categories[category]" type="checkbox"><span>{{ category === 'achievements' ? 'Достижения' : category === 'transfers' ? 'Переводы' : category === 'payments' ? 'Платежи' : category === 'adminActions' ? 'Админ-действия' : 'Релизы' }}</span></label><div v-if="account.user?.role === 'SUPERADMIN'" class="confirm"><input v-model="adminTelegramReason" placeholder="Причина изменения"><input v-model="adminTelegramPassword" type="password" placeholder="Пароль суперадмина"><button class="button gold" :disabled="submitting || adminTelegramReason.trim().length < 5 || !adminTelegramPassword" @click="saveAdminTelegramSettings">Сохранить</button></div><small v-else>Настройки изменяет только суперадминистратор.</small></article></div></section>
      <section v-if="activeTab === 'users'" class="content"><div class="section-head"><div><p class="eyebrow">Профили и прогресс</p><h2>Участники</h2></div><div class="search">⌕ <input v-model="query" placeholder="Логин или телефон" @keyup.enter="loadBase"><button class="button gold" @click="loadBase">Найти</button></div></div><div class="card users-card"><div v-if="loading" class="empty">Загрузка участников…</div><div v-else-if="!users.length" class="empty">Ничего не найдено.</div><button v-for="user in users" :key="user.id" class="user-row" @click="loadDetail(user)"><span class="avatar">{{ user.username.slice(0,1).toUpperCase() }}</span><span class="user-main"><b>{{ user.username }}</b><small>{{ user.phone || 'Телефон не указан' }} · {{ user.role }}</small></span><span v-if="user.blockedAt" class="tag">Заблокирован</span><strong>{{ money(user.balance) }} <small>очков</small></strong><span class="chevron">›</span></button></div></section>
      <section v-if="activeTab === 'economy'" class="content"><div class="section-head"><div><p class="eyebrow">Резервы и выплаты</p><h2>Экономика мини-игр</h2></div><span class="live-dot">● Live</span></div><div class="banks"><article><span>Мины · резерв</span><b>{{ money(economy?.minesBank) }}</b><small>очков для выплат</small></article><article><span>Ракета · резерв</span><b>{{ money(economy?.rocketBank) }}</b><small>очков для выплат</small></article><article><span>Джекпот</span><b>{{ money(economy?.jackpot) }}</b><small>пот текущего сезона</small></article></div><article class="card form-card"><p class="eyebrow">Только суперадмин</p><h3>Редактирование банков</h3><div class="fields"><label>Резерв мин<input v-model.number="economyEdit.minesBank" type="number" min="0"></label><label>Резерв ракеты<input v-model.number="economyEdit.rocketBank" type="number" min="0"></label><label>Джекпот, очки<input v-model.number="economyEdit.jackpotTenths" type="number" min="0"></label></div><div class="confirm"><input v-model="economyEdit.reason" placeholder="Причина изменения"><input v-model="economyEdit.password" type="password" placeholder="Пароль суперадмина"><button class="button gold" :disabled="submitting" @click="saveEconomy">Сохранить банки</button></div></article></section>
      <section v-if="activeTab === 'seasons'" class="content"><div class="section-head"><div><p class="eyebrow">Рейтинги и награды</p><h2>Сезоны</h2></div></div><div class="card list"><div v-for="season in seasons" :key="season.id" class="season-row"><b class="season-no">№{{ season.number }}</b><span><b>{{ season.status === 'active' ? 'Активный сезон' : 'Сезон завершён' }}</b><small>{{ date(season.startsAt) }} — {{ date(season.endsAt) }}</small></span><small>{{ season._count.stats }} игроков · {{ season._count.rewards }} наград</small></div><div v-if="!seasons.length" class="empty">Сезонов пока нет.</div></div></section>
      <section v-if="activeTab === 'audit'" class="content"><div class="section-head"><div><p class="eyebrow">Прозрачность</p><h2>Журнал аудита</h2></div></div><div class="card list"><div v-for="entry in audits" :key="entry.id" class="audit-row"><span class="audit-icon">✓</span><span><b>{{ entry.action }}</b><small>{{ entry.reason }} · {{ entry.entityId || 'система' }}</small></span><time>{{ date(entry.createdAt) }}</time></div><div v-if="!audits.length" class="empty">Записей пока нет.</div></div></section></template>
    <dialog ref="userDialog" class="dialog" aria-label="Редактирование участника" @cancel.prevent="closeUserDialog" @close="selected = null">
      <div class="dialog-head"><div><p class="eyebrow">Редактирование участника</p><h2>{{ selected?.username }}</h2><small>{{ selected?.phone || 'Телефон не указан' }}</small></div><button class="close" :disabled="submitting" aria-label="Закрыть" @click="closeUserDialog">×</button></div>
      <p v-if="error" class="notice error" role="alert">{{ error }}</p>
      <p v-if="notice" class="notice success" role="status">{{ notice }}</p>
      <div class="scroll">
        <section class="dialog-section"><h3>Профиль</h3><div class="fields"><label>Логин<input v-model="edit.username"></label><label>Телефон<input v-model="edit.phone"></label><label>Роль<select v-model="edit.role"><option value="USER">Пользователь</option><option value="ADMIN">Администратор</option><option value="SUPERADMIN">Владелец</option></select></label><label>Рейтинг стола<input v-model.number="edit.tableRating" type="number"></label><label>Рейтинг прогнозов<input v-model.number="edit.predictionRating" type="number"></label><label>Игр за столом<input v-model.number="edit.tableHandsPlayed" type="number"></label><label>Побед за столом<input v-model.number="edit.tableHandsWon" type="number"></label><label>Текущая серия<input v-model.number="edit.tableCurrentStreak" type="number"></label><label>Лучшая серия<input v-model.number="edit.tableBestStreak" type="number"></label></div><div class="confirm"><input v-model="edit.reason" placeholder="Причина изменения"><input v-model="edit.password" type="password" placeholder="Пароль администратора"><button class="button gold" :disabled="submitting" @click="saveProfile">Сохранить профиль</button></div></section>
        <section class="dialog-section"><h3>Достижения</h3><div class="achievements"><div v-for="achievement in achievements" :key="achievement.id"><AchievementBadge :code="achievement.code" :size="28"/><b>{{ achievement.title }}</b><small>{{ achievement.rarity }}</small><button class="button tiny" @click="achievementCommand(achievement.id, selected?.achievements?.some((item: any) => item.achievementId === achievement.id) ? 'revoke' : 'grant')">{{ selected?.achievements?.some((item: any) => item.achievementId === achievement.id) ? 'Снять' : 'Выдать' }}</button></div></div></section>
        <section class="dialog-section balance-section"><div class="section-title"><div><h3>Баланс пользователя</h3><small>Изменение сохраняется через защищённую операцию и журнал аудита.</small></div><strong>{{ money(selected?.balance) }} очков</strong></div><div class="fields"><label>Действие<select v-model="form.action"><option value="credit">Начислить</option><option value="debit">Списать</option><option value="set-balance">Установить баланс</option><option value="block">Заблокировать</option><option value="unblock">Разблокировать</option><option value="revoke">Отозвать сессии</option><option value="archive">Архивировать</option></select></label><label>Сумма операции<input v-model.number="form.amount" type="number" min="0" step="1"></label><label>Подтвердить текущий баланс<input v-model.number="form.expectedBalance" type="number" min="0" step="1"></label></div><div class="confirm"><input v-model="form.reason" placeholder="Причина операции"><input v-model="form.password" type="password" placeholder="Пароль администратора"><button class="button danger" :disabled="submitting" @click="basicCommand">Сохранить изменение</button></div></section>
        <section class="dialog-section premium-admin"><div class="section-title"><div><p class="eyebrow">PREMIUM</p><h3>Управление подпиской</h3><small>Один тариф и одна дата окончания — без технических флагов.</small></div><span class="premium-status" :class="{ active: selected?.premium?.active }">{{ selected?.premium?.active ? `Premium ${selected.premium.plan}` : 'Не активен' }}</span></div><div v-if="selected?.premium?.active" class="premium-expiry"><span>Действует до</span><strong>{{ date(selected.premium.expiresAt) }}</strong></div><div class="premium-controls"><label>Тариф<select v-model="premiumForm.plan"><option value="LITE">Lite</option><option value="PRO">Pro</option><option value="ELITE">Elite</option></select></label><input v-model="premiumForm.reason" placeholder="Причина изменения"><input v-model="premiumForm.password" type="password" placeholder="Пароль администратора"></div><div class="premium-actions"><button class="button gold" :disabled="submitting || !premiumForm.password || premiumForm.reason.trim().length < 5" @click="premiumCommand('assign')">{{ selected?.premium?.active ? 'Сменить тариф · 30 дней' : 'Назначить · 30 дней' }}</button><button class="button ghost" :disabled="submitting || !selected?.premium?.active || !premiumForm.password || premiumForm.reason.trim().length < 5" @click="premiumCommand('extend')">Продлить на 30 дней</button><button class="button premium-off" :disabled="submitting || !selected?.premium?.active || !premiumForm.password || premiumForm.reason.trim().length < 5" @click="premiumCommand('disable')">Отключить</button></div></section>
        <section class="dialog-section reset-section"><div><h3>Сброс мини-игр</h3><p>Удалит историю и текущее состояние «Мин» и «Ракетки». Баланс, профиль, достижения, Telegram и покерные данные не изменяются.</p></div><button class="button ghost" :disabled="submitting" @click="resetMiniGames">Сбросить мини-игры</button></section>
      </div>
    </dialog>
  </main>
